/****** Objeto: StoredProcedure [dbo].[BitacoraEvento_Filtrar] Fecha de script: 03/11/2026 18:42:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[BitacoraEvento_Filtrar]
    @DNI varchar(50) = NULL,
    @NombreUsuario varchar(50) = NULL,
    @Modulo varchar(50) = NULL,
    @Criticidad int = NULL,
    @FechaInicio varchar(30) = NULL,
    @FechaFin varchar(30) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT b.Numero, b.Fecha, b.Modulo, b.Descripcion, b.Criticidad, b.DNI, b.NombreUsuario,
           ISNULL(u.Nombre, '') AS Nombre, ISNULL(u.Apellido, '') AS Apellido
    FROM BitacoraEvento b
    LEFT JOIN Usuarios u ON b.DNI = u.DNI
    WHERE (@DNI IS NULL OR b.DNI = @DNI)
      AND (@NombreUsuario IS NULL OR b.NombreUsuario LIKE @NombreUsuario)
      AND (@Modulo IS NULL OR b.Modulo = @Modulo)
      AND (@Criticidad IS NULL OR b.Criticidad = @Criticidad)
      AND (@FechaInicio IS NULL OR b.Fecha >= @FechaInicio)
      AND (@FechaFin IS NULL OR b.Fecha <= @FechaFin)
    ORDER BY b.Fecha DESC;
END
GO
