CREATE   PROC [dbo].[BitacoraEvento_Registrar]
    @Fecha datetime,
    @Modulo varchar(50),
    @Descripcion varchar(255),
    @Criticidad int,
    @DNI varchar(50),
    @NombreUsuario varchar(50)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO BitacoraEvento (Fecha, Modulo, Descripcion, Criticidad, DNI, NombreUsuario)
    VALUES (@Fecha, @Modulo, @Descripcion, @Criticidad, @DNI, @NombreUsuario);
    SELECT CAST(SCOPE_IDENTITY() AS int) AS Numero;
END
