/* ------------------------------------------------------------
   7) Carrito_ActualizarEstado - NUEVO. Para pasar el carrito
      a "Facturado" cuando la venta se completa (asi no vuelve
      a aparecer como activo, y queda el historico).
   ------------------------------------------------------------ */

CREATE   PROC [dbo].[Carrito_ActualizarEstado]
    @IdCarrito INT,
    @Estado VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE Carrito SET Estado = @Estado WHERE IdCarrito = @IdCarrito;
END
