-- ------------------------------------------------------------
-- Carrito_Agregar (cabecera) - devuelve el IdCarrito generado
-- ------------------------------------------------------------
CREATE   PROC [dbo].[Carrito_Agregar]
    @DNICliente varchar(10),
    @Fecha datetime,
    @Total decimal(10,2),
    @Estado varchar(20)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO Carrito (DNICliente, Fecha, Total, Estado)
    VALUES (@DNICliente, @Fecha, @Total, @Estado);

    SELECT CAST(SCOPE_IDENTITY() AS int) AS IdCarrito;
END
