/* ------------------------------------------------------------
   6) Carrito_ObtenerActivoPorDNI - NUEVO. Hasta ahora el
      Mapper de Carrito solo buscaba por IdCarrito; CUN04
      necesita encontrar el carrito "Activo" de un DNI.
   ------------------------------------------------------------ */

CREATE   PROC [dbo].[Carrito_ObtenerActivoPorDNI]
    @DNICliente VARCHAR(10)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1 IdCarrito, DNICliente, Fecha, Total, Estado
    FROM Carrito
    WHERE DNICliente = @DNICliente AND Estado = 'Activo'
    ORDER BY Fecha DESC;
END
