/****** Objeto: StoredProcedure [dbo].[DetalleImportacion_ProcesarLinea] Fecha de script: 03/11/2026 18:42:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Importa UNA linea valida, todo o nada:
--  * si la linea ya estaba importada (Alta / SumaStock) no hace nada y devuelve 'YaImportada' (no se suma dos veces)
--  * si el producto existe (marca + modelo + color + talle) le suma el stock y NO toca el precio
--  * si no existe lo crea con ese stock y ese precio
--  * deja la linea registrada (si estaba rechazada, la actualiza)
CREATE   PROC [dbo].[DetalleImportacion_ProcesarLinea]
    @IdImportacion int,
    @Linea int,
    @IdMarca int,
    @IdCategoria int,
    @Marca varchar(50),
    @Categoria varchar(50),
    @Modelo varchar(50),
    @Color varchar(30),
    @Talle varchar(10),
    @Cantidad int,
    @Precio decimal(18,2)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @IdDetalle int, @AccionPrevia varchar(20), @IdProducto int, @Accion varchar(20);

    BEGIN TRAN;

    SELECT @IdDetalle = IdDetalleImportacion, @AccionPrevia = Accion, @IdProducto = IdProducto
    FROM DetalleImportacion WITH (UPDLOCK, HOLDLOCK)
    WHERE IdImportacion = @IdImportacion AND Linea = @Linea;

    IF @AccionPrevia IS NOT NULL AND @AccionPrevia <> 'Rechazada'
    BEGIN
        COMMIT;
        SELECT CAST('YaImportada' AS varchar(20)) AS Accion, ISNULL(@IdProducto, 0) AS IdProducto;
        RETURN;
    END

    SET @IdProducto = NULL;

    SELECT @IdProducto = IdProducto
    FROM Producto WITH (UPDLOCK, HOLDLOCK)
    WHERE IdMarca = @IdMarca AND Modelo = @Modelo AND Color = @Color AND Talle = @Talle;

    IF @IdProducto IS NULL
    BEGIN
        INSERT INTO Producto (IdMarca, IdCategoria, Modelo, Color, Talle, Precio, Stock)
        VALUES (@IdMarca, @IdCategoria, @Modelo, @Color, @Talle, @Precio, @Cantidad);
        SET @IdProducto = CAST(SCOPE_IDENTITY() AS int);
        SET @Accion = 'Alta';
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM Producto WHERE IdProducto = @IdProducto AND CAST(Stock AS bigint) + @Cantidad > 2147483647)
            THROW 50001, 'El stock resultante supera el maximo permitido.', 1;

        UPDATE Producto SET Stock = Stock + @Cantidad WHERE IdProducto = @IdProducto;
        SET @Accion = 'SumaStock';
    END

    IF @IdDetalle IS NULL
        INSERT INTO DetalleImportacion (IdImportacion, Linea, Marca, Categoria, Modelo, Color, Talle, Cantidad, Precio, Accion, IdProducto, Motivo)
        VALUES (@IdImportacion, @Linea, @Marca, @Categoria, @Modelo, @Color, @Talle,
                CAST(@Cantidad AS varchar(30)), CAST(@Precio AS varchar(30)), @Accion, @IdProducto, NULL);
    ELSE
        UPDATE DetalleImportacion
        SET Marca = @Marca, Categoria = @Categoria, Modelo = @Modelo, Color = @Color, Talle = @Talle,
            Cantidad = CAST(@Cantidad AS varchar(30)), Precio = CAST(@Precio AS varchar(30)),
            Accion = @Accion, IdProducto = @IdProducto, Motivo = NULL
        WHERE IdDetalleImportacion = @IdDetalle;

    COMMIT;

    SELECT @Accion AS Accion, @IdProducto AS IdProducto;
END

GO
