-- Deja registrada una linea rechazada con su motivo. Si la linea ya estaba importada, no la toca
CREATE   PROC [dbo].[DetalleImportacion_RegistrarRechazo]
    @IdImportacion int,
    @Linea int,
    @Marca varchar(100),
    @Categoria varchar(100),
    @Modelo varchar(100),
    @Color varchar(100),
    @Talle varchar(30),
    @Cantidad varchar(30),
    @Precio varchar(30),
    @Motivo varchar(500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @IdDetalle int, @AccionPrevia varchar(20);

    BEGIN TRAN;

    SELECT @IdDetalle = IdDetalleImportacion, @AccionPrevia = Accion
    FROM DetalleImportacion WITH (UPDLOCK, HOLDLOCK)
    WHERE IdImportacion = @IdImportacion AND Linea = @Linea;

    IF @IdDetalle IS NULL
        INSERT INTO DetalleImportacion (IdImportacion, Linea, Marca, Categoria, Modelo, Color, Talle, Cantidad, Precio, Accion, IdProducto, Motivo)
        VALUES (@IdImportacion, @Linea, @Marca, @Categoria, @Modelo, @Color, @Talle, @Cantidad, @Precio, 'Rechazada', NULL, @Motivo);
    ELSE IF @AccionPrevia = 'Rechazada'
        UPDATE DetalleImportacion
        SET Marca = @Marca, Categoria = @Categoria, Modelo = @Modelo, Color = @Color, Talle = @Talle,
            Cantidad = @Cantidad, Precio = @Precio, Motivo = @Motivo
        WHERE IdDetalleImportacion = @IdDetalle;

    COMMIT;
END

