/* ---------------------------------------------------------------------------
   3b) Los 4 SP de detalle que traian p.Marca ahora leen la marca con JOIN
   --------------------------------------------------------------------------- */
CREATE   PROC [dbo].[DetalleOrdenCompra_ListarPorOrden]
    @IdOrden INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT d.IdDetalleOrden, d.IdOrden, d.IdProducto, d.Cantidad, d.CostoUnitario, d.Subtotal, d.DV,
           m.Nombre AS Marca, p.Modelo, p.Color, p.Talle
    FROM DetalleOrdenCompra d
    JOIN Producto p ON p.IdProducto = d.IdProducto
    JOIN Marca m ON m.IdMarca = p.IdMarca
    WHERE d.IdOrden = @IdOrden;
END

