GO
CREATE   PROC [dbo].[DetalleOrdenCompra_ObtenerUltimoCosto]
    @IdProducto INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1 d.CostoUnitario
    FROM DetalleOrdenCompra d
    JOIN OrdenCompra o ON o.IdOrden = d.IdOrden
    WHERE d.IdProducto = @IdProducto
    ORDER BY o.Fecha DESC;
END
