/* ------------------------------------------------------------
   2) SPs de Factura. Arranca en "Pendiente de Pago" (MedioPago
      NULL todavia); ActualizarEstadoYPago la pasa a "Pagada"
      con el medio de pago usado, en un solo UPDATE.
   ------------------------------------------------------------ */

CREATE   PROC [dbo].[Factura_Agregar]
    @Fecha DATETIME,
    @IdOrden INT,
    @Total DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO Factura (NroFactura, Fecha, IdOrden, MedioPago, Total, Estado)
    VALUES ('', @Fecha, @IdOrden, NULL, @Total, 'Pendiente de Pago');

    DECLARE @IdFactura INT = SCOPE_IDENTITY();
    DECLARE @NroFactura VARCHAR(20) = RIGHT('000000' + CAST(@IdFactura AS VARCHAR(10)), 6);

    UPDATE Factura SET NroFactura = @NroFactura WHERE IdFactura = @IdFactura;

    SELECT @IdFactura;
END
GO
