/****** Objeto: StoredProcedure [dbo].[ImportacionProducto_Cerrar] Fecha de script: 03/11/2026 18:42:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Cuenta las lineas del remito y deja el estado: Completo solo si hay lineas importadas y ninguna rechazada.
-- Devuelve el estado
CREATE   PROC [dbo].[ImportacionProducto_Cerrar]
    @IdImportacion int,
    @Usuario varchar(100),
    @NombreArchivo varchar(260)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE ImportacionProducto
    SET LineasAlta = (SELECT COUNT(1) FROM DetalleImportacion d WHERE d.IdImportacion = @IdImportacion AND d.Accion = 'Alta'),
        LineasSuma = (SELECT COUNT(1) FROM DetalleImportacion d WHERE d.IdImportacion = @IdImportacion AND d.Accion = 'SumaStock'),
        LineasRechazadas = (SELECT COUNT(1) FROM DetalleImportacion d WHERE d.IdImportacion = @IdImportacion AND d.Accion = 'Rechazada'),
        Estado = CASE WHEN EXISTS (SELECT 1 FROM DetalleImportacion d WHERE d.IdImportacion = @IdImportacion AND d.Accion <> 'Rechazada')
                       AND NOT EXISTS (SELECT 1 FROM DetalleImportacion d WHERE d.IdImportacion = @IdImportacion AND d.Accion = 'Rechazada')
                      THEN 'Completo' ELSE 'ConRechazos' END,
        FechaImportacion = GETDATE(),
        Usuario = @Usuario,
        NombreArchivo = @NombreArchivo
    WHERE IdImportacion = @IdImportacion;

    SELECT Estado FROM ImportacionProducto WHERE IdImportacion = @IdImportacion;
END

GO
/****** Objeto: StoredProcedure [dbo].[ImportacionProducto_Crear] Fecha de script: 03/11/2026 18:42:09 ******/
SET ANSI_NULLS ON
