-- 2) SP que registra el remito la primera vez que llega (ahora con la huella del contenido)
CREATE   PROC [dbo].[ImportacionProducto_Crear]
    @IdProveedor int,
    @NroRemito varchar(30),
    @Usuario varchar(100),
    @NombreArchivo varchar(260),
    @HashContenido varchar(64) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO ImportacionProducto (IdProveedor, NroRemito, Usuario, NombreArchivo, HashContenido)
    VALUES (@IdProveedor, @NroRemito, @Usuario, @NombreArchivo, @HashContenido);
    SELECT CAST(SCOPE_IDENTITY() AS int);
END
GO
/****** Objeto: StoredProcedure [dbo].[ImportacionProducto_ObtenerPorHuella] Fecha de script: 03/11/2026 18:42:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- SP que busca si ese proveedor ya importo antes el mismo contenido (con otro numero de remito)
CREATE   PROC [dbo].[ImportacionProducto_ObtenerPorHuella]
    @IdProveedor int,
    @HashContenido varchar(64)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1 IdImportacion, IdProveedor, NroRemito, Estado, FechaImportacion, Usuario, NombreArchivo,
           LineasAlta, LineasSuma, LineasRechazadas
    FROM ImportacionProducto
    WHERE IdProveedor = @IdProveedor AND HashContenido = @HashContenido
    ORDER BY IdImportacion;
END
GO
