CREATE   PROC [dbo].[OrdenCompra_Agregar]
    @Fecha DATETIME,
    @IdProveedor INT,
    @IdSolicitud INT,
    @CostoTotal DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO OrdenCompra (NroOrden, Fecha, IdProveedor, IdSolicitud, CostoTotal, Estado)
    VALUES ('', @Fecha, @IdProveedor, @IdSolicitud, @CostoTotal, 'Pendiente de Recepción');

    DECLARE @IdOrden INT = SCOPE_IDENTITY();
    DECLARE @NroOrden VARCHAR(20) = RIGHT('000000' + CAST(@IdOrden AS VARCHAR(10)), 6);

    UPDATE OrdenCompra SET NroOrden = @NroOrden WHERE IdOrden = @IdOrden;

    SELECT @IdOrden;
END
