-- Devuelve solo nombres (no una entidad), se lee directo sin mapeo por reflexion.
-- Union de: permisos sueltos del perfil + permisos que vienen via familias asignadas.
CREATE   PROC [dbo].[Perfil_ObtenerPermisosPorRol]
    @NombreRol varchar(100)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT DISTINCT p.Nombre
    FROM Permiso p
    INNER JOIN Perfil_Permiso pp ON p.IdPermiso = pp.IdPermiso
    INNER JOIN Perfil per ON pp.IdPerfil = per.IdPerfil
    WHERE per.Nombre = @NombreRol

    UNION

    SELECT DISTINCT p.Nombre
    FROM Permiso p
    INNER JOIN Familia_Permiso fp ON p.IdPermiso = fp.IdPermiso
    INNER JOIN Perfil_Familia pf ON fp.IdFamilia = pf.IdFamilia
    INNER JOIN Perfil per ON pf.IdPerfil = per.IdPerfil
    WHERE per.Nombre = @NombreRol;
END
GO
