-- 4) Descuento de stock con control: si no alcanza, no descuenta y devuelve error
CREATE PROC [dbo].[Producto_ActualizarStock]
    @IdProducto INT,
    @Cantidad INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Descuenta stock (venta). Nunca deja el stock en negativo: si no alcanza (o el producto no existe) no descuenta y devuelve un error
    UPDATE Producto SET Stock = Stock - @Cantidad
    WHERE IdProducto = @IdProducto AND Stock >= @Cantidad;

    IF @@ROWCOUNT = 0
        THROW 50001, 'Stock insuficiente o producto inexistente.', 1;
END
GO
