-- Filtros opcionales: un parametro en NULL se ignora. @SoloConStock = 0 no filtra por stock.
-- El filtro de marca se aplica sobre el NOMBRE de la marca.
CREATE   PROC [dbo].[Producto_Buscar]
    @Marca varchar(50) = NULL,
    @Modelo varchar(50) = NULL,
    @Color varchar(50) = NULL,
    @Talle varchar(10) = NULL,
    @SoloConStock bit = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT p.IdProducto, p.IdMarca, m.Nombre AS Marca, p.IdCategoria, c.Nombre AS Categoria,
           p.Modelo, p.Color, p.Talle, p.Precio, p.Stock
    FROM Producto p
    JOIN Marca m ON m.IdMarca = p.IdMarca
    JOIN Categoria c ON c.IdCategoria = p.IdCategoria
    WHERE (@Marca  IS NULL OR m.Nombre LIKE '%' + @Marca  + '%')
      AND (@Modelo IS NULL OR p.Modelo LIKE '%' + @Modelo + '%')
      AND (@Color  IS NULL OR p.Color  LIKE '%' + @Color  + '%')
      AND (@Talle  IS NULL OR p.Talle  LIKE '%' + @Talle  + '%')
      AND (@SoloConStock = 0 OR p.Stock > 0);
END

GO
