    @IdMarca int,
    @Modelo varchar(50),
    @Color varchar(30),
    @Talle varchar(10),
    @IdExcluir int = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT COUNT(1)
    FROM Producto
    WHERE IdMarca = @IdMarca AND Modelo = @Modelo AND Color = @Color AND Talle = @Talle
      AND IdProducto <> @IdExcluir;
END

