-- Un producto o un proveedor que figura en una importacion tampoco se puede eliminar
CREATE   PROC [dbo].[Producto_TieneMovimientos]
    @IdProducto int
AS
BEGIN
    SET NOCOUNT ON;
    SELECT CASE WHEN EXISTS (SELECT 1 FROM DetalleCarrito WHERE IdProducto = @IdProducto)
                  OR EXISTS (SELECT 1 FROM DetalleVenta WHERE IdProducto = @IdProducto)
                  OR EXISTS (SELECT 1 FROM DetalleSolicitudCompra WHERE IdProducto = @IdProducto)
                  OR EXISTS (SELECT 1 FROM DetalleOrdenCompra WHERE IdProducto = @IdProducto)
                  OR EXISTS (SELECT 1 FROM DetalleRecepcion WHERE IdProducto = @IdProducto)
                  OR EXISTS (SELECT 1 FROM DetalleImportacion WHERE IdProducto = @IdProducto)
                THEN 1 ELSE 0 END;
END

GO
