CREATE   PROC [dbo].[Recepcion_Agregar]
    @Fecha DATETIME,
    @IdOrden INT
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO Recepcion (NroRecepcion, Fecha, IdOrden)
    VALUES ('', @Fecha, @IdOrden);

    DECLARE @IdRecepcion INT = SCOPE_IDENTITY();
    DECLARE @NroRecepcion VARCHAR(20) = RIGHT('000000' + CAST(@IdRecepcion AS VARCHAR(10)), 6);

    UPDATE Recepcion SET NroRecepcion = @NroRecepcion WHERE IdRecepcion = @IdRecepcion;

    SELECT @IdRecepcion;
END
