/****** Objeto: StoredProcedure [dbo].[Reporte_ClientesFrecuentes] Fecha de script: 03/11/2026 18:42:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[Reporte_ClientesFrecuentes]
    @Desde DATETIME,
    @Hasta DATETIME,
    @MinCompras INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Clientes con al menos @MinCompras compras entre @Desde y @Hasta (inclusive ambos dias), de mayor a menor monto gastado.
    -- No devuelve el correo (esta encriptado). Toda venta registrada cuenta (Venta no tiene estado).
    SELECT c.DNI,
           c.Nombre,
           c.Apellido,
           COUNT(v.IdVenta) AS CantidadCompras,
           SUM(v.Total)     AS TotalGastado,
           MAX(v.Fecha)     AS UltimaCompra
    FROM Venta v
    INNER JOIN Cliente c ON c.DNI = v.DNICliente
    WHERE v.Fecha >= @Desde
      AND v.Fecha <  DATEADD(DAY, 1, @Hasta)
    GROUP BY c.DNI, c.Nombre, c.Apellido
    HAVING COUNT(v.IdVenta) >= @MinCompras
    ORDER BY SUM(v.Total) DESC, c.Apellido, c.Nombre;
END
GO
/****** Objeto: StoredProcedure [dbo].[Reporte_EstadoStock] Fecha de script: 03/11/2026 18:42:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[Reporte_EstadoStock]
    @Marca       VARCHAR(50) = NULL,
    @Talle       VARCHAR(10) = NULL,
    @Estado      INT         = NULL,
    @SoloReponer BIT         = 0,
    @UmbralBajo  INT         = 5
AS
BEGIN
    SET NOCOUNT ON;

    -- Estado: 0 = sin stock, 1 = stock bajo (de 1 hasta @UmbralBajo unidades), 2 = normal (mas de @UmbralBajo).
    -- Cada filtro en NULL no filtra. @SoloReponer = 1 deja solo los de estado 0 y 1.
    SELECT t.Marca, t.Modelo, t.Color, t.Talle, t.Stock, t.Precio, t.ValorStock, t.Estado
    FROM (
        SELECT m.Nombre AS Marca,
               p.Modelo,
               p.Color,
               p.Talle,
               p.Stock,
               p.Precio,
               CAST(p.Stock * p.Precio AS DECIMAL(18, 2)) AS ValorStock,
               CASE WHEN p.Stock <= 0 THEN 0
                    WHEN p.Stock <= @UmbralBajo THEN 1
                    ELSE 2 END AS Estado
        FROM Producto p
        INNER JOIN Marca m ON m.IdMarca = p.IdMarca
    ) t
    WHERE (@Marca IS NULL OR t.Marca = @Marca)
      AND (@Talle IS NULL OR t.Talle = @Talle)
      AND (@Estado IS NULL OR t.Estado = @Estado)
      AND (@SoloReponer = 0 OR t.Estado IN (0, 1))
    ORDER BY t.Estado, t.Marca, t.Modelo, t.Color, t.Talle;
END
GO
