-- 2) Totales del rango (siempre devuelve una fila, aunque no haya ventas)
CREATE   PROC [dbo].[Reporte_ResumenVentas]
    @Desde date,
    @Hasta date
AS
BEGIN
    SET NOCOUNT ON;

    SELECT COUNT(v.IdVenta) AS CantidadVentas,
           ISNULL(SUM(v.Total), 0) AS MontoTotal,
           ISNULL(SUM(u.Unidades), 0) AS Unidades
    FROM dbo.Venta v
    LEFT JOIN (SELECT IdVenta, SUM(Cantidad) AS Unidades FROM dbo.DetalleVenta GROUP BY IdVenta) u ON u.IdVenta = v.IdVenta
    WHERE v.Fecha >= @Desde AND v.Fecha < DATEADD(DAY, 1, @Hasta);
END
GO
