-- 3) Modelos mas vendidos (por unidades). Suma todos los colores y talles de un mismo modelo.
CREATE   PROC [dbo].[Reporte_TopProductos]
    @Desde date,
    @Hasta date,
    @Cantidad int
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP (@Cantidad)
           m.Nombre AS Marca,
           p.Modelo AS Modelo,
           SUM(d.Cantidad) AS Unidades,
           SUM(d.Subtotal) AS Monto
    FROM dbo.Venta v
    INNER JOIN dbo.DetalleVenta d ON d.IdVenta = v.IdVenta
    INNER JOIN dbo.Producto p ON p.IdProducto = d.IdProducto
    INNER JOIN dbo.Marca m ON m.IdMarca = p.IdMarca
    WHERE v.Fecha >= @Desde AND v.Fecha < DATEADD(DAY, 1, @Hasta)
    GROUP BY m.Nombre, p.Modelo
    ORDER BY SUM(d.Cantidad) DESC, SUM(d.Subtotal) DESC, m.Nombre, p.Modelo;
END
GO
