-- 4) Ventas por medio de pago
CREATE   PROC [dbo].[Reporte_VentasMedioPago]
    @Desde date,
    @Hasta date
AS
BEGIN
    SET NOCOUNT ON;

    SELECT v.MedioPago AS MedioPago,
           COUNT(*) AS CantidadVentas,
           SUM(v.Total) AS MontoTotal
    FROM dbo.Venta v
    WHERE v.Fecha >= @Desde AND v.Fecha < DATEADD(DAY, 1, @Hasta)
    GROUP BY v.MedioPago
    ORDER BY SUM(v.Total) DESC, v.MedioPago;
END
