/* ------------------------------------------------------------
   2) Venta_Agregar: inserta la cabecera y genera el
      NroComprobante a partir del propio IdVenta (padding a
      6 digitos, ej. 000123). Devuelve el IdVenta.
   ------------------------------------------------------------ */

CREATE   PROC [dbo].[Venta_Agregar]
    @Fecha DATETIME,
    @DNICliente VARCHAR(10),
    @MedioPago VARCHAR(20),
    @Total DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO Venta (NroComprobante, Fecha, DNICliente, MedioPago, Total)
    VALUES ('', @Fecha, @DNICliente, @MedioPago, @Total);

    DECLARE @IdVenta INT = SCOPE_IDENTITY();
    DECLARE @NroComprobante VARCHAR(20) = RIGHT('000000' + CAST(@IdVenta AS VARCHAR(10)), 6);

    UPDATE Venta SET NroComprobante = @NroComprobante WHERE IdVenta = @IdVenta;

    SELECT @IdVenta;
END
GO
